import{_ as s,o,c as t,a2 as a}from"./chunks/framework.hw3Av5Vn.js";const u=JSON.parse('{"title":"User Scripts","description":"","frontmatter":{},"headers":[],"relativePath":"USER_SCRIPTS.md","filePath":"USER_SCRIPTS.md"}'),i={name:"USER_SCRIPTS.md"};function n(d,e,l,r,c,h){return o(),t("div",null,[...e[0]||(e[0]=[a('<h1 id="user-scripts" tabindex="-1">User Scripts <a class="header-anchor" href="#user-scripts" aria-label="Permalink to &quot;User Scripts&quot;">​</a></h1><p>The scripts in <code>user_scripts/</code> are for anyone using llamatron, as opposed to the development tools in <code>internal_tools/</code>. Each is plain <code>sh</code>, so it needs nothing installed first, and each runs from the project folder wherever it is started, passing on any options it is given. Run one from the project folder as <code>sh user_scripts/NAME.sh</code>.</p><p>Each script below has an example of running it and a list of its parameters, in the order they are given: first what the script is given in place, such as the set to record, and then its options, which may come in any order.</p><h2 id="installation" tabindex="-1">Installation <a class="header-anchor" href="#installation" aria-label="Permalink to &quot;Installation&quot;">​</a></h2><h3 id="setup-sh" tabindex="-1"><code>setup.sh</code> <a class="header-anchor" href="#setup-sh" aria-label="Permalink to &quot;`setup.sh`&quot;">​</a></h3><p>Installs what llamatron needs and builds it: it makes <code>.venv</code>, a small Python environment the development tools use, then runs <code>build.sh</code>, which offers to install Rust first. Run it once after cloning the repository. <a href="./INSTALLING">Installing</a> describes the installation.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>sh setup.sh</span></span></code></pre></div><p>Parameters: none.</p><h3 id="build-sh" tabindex="-1"><code>build.sh</code> <a class="header-anchor" href="#build-sh" aria-label="Permalink to &quot;`build.sh`&quot;">​</a></h3><p>Builds llamatron, which <code>./llamatron.sh</code> opens, offering to install Rust first (<a href="./BUILDING_THE_BACKEND">Building llamatron</a>). Run it once after cloning the repository, and again after updating it.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>sh build.sh</span></span></code></pre></div><p>Parameters: none.</p><h3 id="install-fluidsynth-sh" tabindex="-1"><code>install_fluidsynth.sh</code> <a class="header-anchor" href="#install-fluidsynth-sh" aria-label="Permalink to &quot;`install_fluidsynth.sh`&quot;">​</a></h3><p>Installs FluidSynth, a free software synthesizer, and the sounds it plays, using Homebrew and offering to install Homebrew first. Run it once if you want to hear the demos with no synthesizer of your own or DAW, or to export WAV files. It installs nothing without asking, and does nothing that is already done. See <a href="./FLUIDSYNTH">FluidSynth</a>.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>sh user_scripts/install_fluidsynth.sh</span></span></code></pre></div><p>Parameters: none.</p><p>Environment:</p><ul><li><code>SOUNDFONT_DIR</code>: the folder to download the SoundFont into, <code>~/soundfonts</code> unless given. llamatron looks for the SoundFont in <code>~/soundfonts</code>.</li></ul><h3 id="install-blackhole-sh" tabindex="-1"><code>install_blackhole.sh</code> <a class="header-anchor" href="#install-blackhole-sh" aria-label="Permalink to &quot;`install_blackhole.sh`&quot;">​</a></h3><p>Installs BlackHole 2ch, the loopback audio device the demo recorder records sound from, using Homebrew and asking before installing. Run it once before recording your first video. See <a href="./INSTALLING_RECORDING">Recording</a>, which also says why the Mac&#39;s output is best left on your speakers while you compose, since the Multi-Output Device made for recording can make the sound substantially quieter.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>sh user_scripts/install_blackhole.sh</span></span></code></pre></div><p>Parameters: none.</p><h2 id="documentation" tabindex="-1">Documentation <a class="header-anchor" href="#documentation" aria-label="Permalink to &quot;Documentation&quot;">​</a></h2><h3 id="launch-docs-sh" tabindex="-1"><code>launch_docs.sh</code> <a class="header-anchor" href="#launch-docs-sh" aria-label="Permalink to &quot;`launch_docs.sh`&quot;">​</a></h3><p>Serves the documentation website on this computer and opens it in the browser, building it first into <code>output/web_docs/</code> where it isn&#39;t built yet or a document has changed since it was built. Use it to read the documentation offline, or to check the website after rebuilding it, before publishing. <code>Ctrl+C</code> stops it.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>sh user_scripts/launch_docs.sh</span></span>\n<span class="line"><span>sh user_scripts/launch_docs.sh --port 8080 --no-browser</span></span></code></pre></div><p>Parameters:</p><ul><li><code>--port PORT</code>: the port to serve on, 4173 unless given.</li><li><code>--no-browser</code>: serve without opening the browser.</li></ul><h2 id="listening-to-the-demos" tabindex="-1">Listening to the Demos <a class="header-anchor" href="#listening-to-the-demos" aria-label="Permalink to &quot;Listening to the Demos&quot;">​</a></h2><h3 id="demos-to-midi-sh" tabindex="-1"><code>demos_to_midi.sh</code> <a class="header-anchor" href="#demos-to-midi-sh" aria-label="Permalink to &quot;`demos_to_midi.sh`&quot;">​</a></h3><p>Exports every example as one General MIDI file in <code>output/previews/</code>, playable in any MIDI player, such as GarageBand. Use it to hear the demos on a computer without llamatron, or to share them.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>sh user_scripts/demos_to_midi.sh</span></span>\n<span class="line"><span>sh user_scripts/demos_to_midi.sh examples/learning/02_pachelbel.yml</span></span></code></pre></div><p>Parameters:</p><ul><li><code>SET ...</code>: the sets to export, every example unless given.</li></ul><h3 id="demos-to-wavs-sh" tabindex="-1"><code>demos_to_wavs.sh</code> <a class="header-anchor" href="#demos-to-wavs-sh" aria-label="Permalink to &quot;`demos_to_wavs.sh`&quot;">​</a></h3><p>Turns every demo into a WAV file in <code>output/previews/</code> in one go: it makes the previews first, plays each through FluidSynth, which it installs the first time, and evens out their loudness. Use it to have every demo as audio to play or share.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>sh user_scripts/demos_to_wavs.sh</span></span>\n<span class="line"><span>sh user_scripts/demos_to_wavs.sh output/previews/pachelbel.mid</span></span></code></pre></div><p>Parameters:</p><ul><li><code>PREVIEW ...</code>: the preview MIDI files to turn into WAV files; every demo, its preview made afresh, unless given.</li></ul><h3 id="demos-to-live-sets-sh" tabindex="-1"><code>demos_to_live_sets.sh</code> <a class="header-anchor" href="#demos-to-live-sets-sh" aria-label="Permalink to &quot;`demos_to_live_sets.sh`&quot;">​</a></h3><p>Exports every example as an Ableton Live set beside it, replacing earlier exports. Use it to open the demos in Live with every scene and clip in place.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>sh user_scripts/demos_to_live_sets.sh</span></span></code></pre></div><p>Parameters: none.</p><h2 id="the-corpus" tabindex="-1">The Corpus <a class="header-anchor" href="#the-corpus" aria-label="Permalink to &quot;The Corpus&quot;">​</a></h2><h3 id="fetch-corpus-sh" tabindex="-1"><code>fetch_corpus.sh</code> <a class="header-anchor" href="#fetch-corpus-sh" aria-label="Permalink to &quot;`fetch_corpus.sh`&quot;">​</a></h3><p>Downloads the public domain music corpus, scores and traditional tunes, into <code>output/corpus/</code>, which git ignores, asking before each collection and saying its size and terms. The song wizard&#39;s music theory was measured from it, and the song wizard is to import songs from it where it is downloaded. <a href="./CREDITS">Credits</a> lists each collection, its link, its terms and its folder.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>sh user_scripts/fetch_corpus.sh</span></span>\n<span class="line"><span>sh user_scripts/fetch_corpus.sh joplin thesession</span></span>\n<span class="line"><span>sh user_scripts/fetch_corpus.sh --all</span></span></code></pre></div><p>Parameters:</p><ul><li><code>COLLECTION ...</code>: the collections to download, by their folders, such as <code>joplin</code>; asked one by one unless given.</li><li><code>--all</code>: every collection, without asking.</li></ul><h2 id="recording-videos" tabindex="-1">Recording Videos <a class="header-anchor" href="#recording-videos" aria-label="Permalink to &quot;Recording Videos&quot;">​</a></h2><p>Recording is coming back to llamatron, which is now written in Rust; until it does, these scripts are not part of it.</p><p>Every recording script needs the setup that <a href="./INSTALLING_RECORDING">Recording</a>, under Installing, describes: BlackHole, Screen Recording permission for your terminal, and Xcode&#39;s command line tools. <a href="./RECORDING">Recording</a> describes the takes themselves.</p><p>The visualizer modes a recording can show are <code>lava_lamp</code>, <code>piano_roll</code>, <code>spectrum</code>, <code>milkdrop</code>, <code>llamas</code>, <code>hypercube</code>, <code>fireworks</code>, <code>warpzone</code>, <code>pipes</code>, <code>plasma</code>, <code>maze</code>, <code>mystify</code>, <code>laser_llama</code>, <code>mandelbrot</code>, <code>life</code>, <code>digital_rain</code> and <code>cycle</code>.</p><h3 id="record-sh" tabindex="-1"><code>record.sh</code> <a class="header-anchor" href="#record-sh" aria-label="Permalink to &quot;`record.sh`&quot;">​</a></h3><p>Records a video of the tracker playing a set on Arrange. <code>--sound</code> says where the sound comes from: <code>daw</code>, the default, plays the set&#39;s tracks over MIDI into your DAW, so the song sounds as your own instruments play it, and <code>fluidsynth</code> plays the set&#39;s own FluidSynth instruments, so no DAW is needed, the simplest recording. With <code>--interactive</code> you perform the take: nothing plays until you press <code>Space</code> on Arrange&#39;s corner, and stopping there, or <code>ESC</code>, ends it, so that you can launch scenes and edit as the song plays. A take of a visualizer opens on the title and READY and fills the screen with the visualizer in its frame, unless <code>--plain</code> is given.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>sh user_scripts/record.sh examples/learning/01_hello_world.yml --sound fluidsynth</span></span>\n<span class="line"><span>sh user_scripts/record.sh examples/learning/01_hello_world.yml --sound fluidsynth --visualizer plasma --go</span></span>\n<span class="line"><span>sh user_scripts/record.sh examples/learning/01_hello_world.yml --sound fluidsynth --interactive</span></span>\n<span class="line"><span>sh user_scripts/record.sh my_set.yml --use-driver &quot;My Synth&quot; --track-assign 1,1,2 --max-seconds 60</span></span>\n<span class="line"><span>sh user_scripts/record.sh my_set.yml --interactive --use-driver &quot;IAC&quot;</span></span></code></pre></div><p>Parameters:</p><ul><li><code>SET</code>: the set to record, such as <code>examples/learning/01_hello_world.yml</code>.</li><li><code>--sound SOUND</code>: <code>daw</code>, the default, or <code>fluidsynth</code>.</li><li><code>--interactive</code>: perform the take yourself.</li><li><code>--visualizer MODE</code>: record this visualizer mode rather than the clips.</li><li><code>--clips</code>: record the clips on Arrange, without asking.</li><li><code>--detail</code>: record the clips on Arrange with the Details View open, as <code>D</code> shows it, without asking; it cannot be combined with <code>--visualizer</code>.</li><li><code>--plain</code>: with <code>--visualizer</code>, show the visualizer over Arrange&#39;s clip area, the older style, rather than the title, READY and the framed visualizer.</li><li><code>--no-alternate</code>: show the visualizer alone in the frame, rather than the clips and the visualizer by turns every ten seconds.</li><li><code>--batch</code>: record the take as one of a batch video&#39;s, from the window&#39;s cells alone.</li><li><code>--scroll-text WORDS</code>: the words that cross the screen after the opening splash, in place of <code>DEMO:</code> and the set&#39;s name from its file.</li><li><code>--no-scroll</code>: show no words crossing the screen after the opening splash.</li><li><code>--announce</code>: show each scene&#39;s name as the scene starts, such as <code>SCENE: verse</code>, near the bottom of the screen, in place of the visualizer modes&#39; names.</li><li><code>--audio-device DEVICE</code>: the audio input device to record the sound from, the first whose name holds this text.</li><li><code>--max-seconds SECONDS</code>: the longest the take may run.</li><li><code>--window-id ID</code>: the id of the window to record, when the terminal program cannot be asked.</li><li><code>--go</code>: start the take at once, without waiting for ENTER after the setup is explained.</li></ul><p>With <code>--sound daw</code>:</p><ul><li><code>--use-driver PORT</code>: the MIDI output port to play through, the first whose name holds this text.</li><li><code>--track-assign-auto</code>: the first track on channel 1, the second on 2 and so on, the default.</li><li><code>--track-assign CHANNELS</code>: a channel for each track in the song&#39;s order, such as <code>1,1,2</code>, with <code>-</code> to keep a track&#39;s own instrument.</li></ul><p>With <code>--sound fluidsynth</code>:</p><ul><li><code>--fluidsynth-output DEVICE</code>: the audio output FluidSynth plays to, such as a Multi-Output Device that reaches the recorded one too; the recorded device unless given.</li></ul><h3 id="record-all-sh" tabindex="-1"><code>record_all.sh</code> <a class="header-anchor" href="#record-all-sh" aria-label="Permalink to &quot;`record_all.sh`&quot;">​</a></h3><p>Records a video of every example through FluidSynth, shortest first, each showing the visualizer mode its pairing gives it, and leaves out any example whose video is already recorded. Use it to make videos of every demo for uploading.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>sh user_scripts/record_all.sh</span></span>\n<span class="line"><span>LLAMATRON_BATCH_RECORD_MAX=2 sh user_scripts/record_all.sh</span></span></code></pre></div><p>Parameters:</p><ul><li><code>--audio-device DEVICE</code>: the audio input device to record the sound from, the first whose name holds this text.</li><li><code>--fluidsynth-output DEVICE</code>: the audio output FluidSynth plays to, such as a Multi-Output Device that reaches the recorded one too.</li><li><code>--window-id ID</code>: the id of the window to record, when the terminal program cannot be asked.</li><li><code>--go</code>: start at once, without waiting for ENTER after the list of takes.</li><li><code>--no-scroll</code>: show no words crossing the screen after each take&#39;s title.</li><li><code>--announce</code>: show each scene&#39;s name as the scene starts, such as <code>SCENE: verse</code>, near the bottom of each video.</li></ul><p>Environment:</p><ul><li><code>LLAMATRON_BATCH_RECORD_MAX</code>: record only this many examples, the shortest, such as <code>2</code> to try it first.</li></ul>',69)])])}const m=s(i,[["render",n]]);export{u as __pageData,m as default};
